<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free JSON Key Counter','description'=>'Count keys, objects and arrays in JSON data.','url'=>'https://smarttoolz.in/tools/json-key-counter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>JSON Key Counter</h1><p>Inspect basic JSON structure instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder="Paste JSON..."></textarea><button id="go" class="tool-btn">Analyze JSON</button><p id="o"></p></div></section></main><script>function walk(x){let k=0,o=0,a=0;if(Array.isArray(x)){a++;x.forEach(v=>{let z=walk(v);k+=z.k;o+=z.o;a+=z.a-1})}else if(x&&typeof x==='object'){o++;Object.entries(x).forEach(([,v])=>{k++;let z=walk(v);k+=z.k;o+=z.o;a+=z.a})}return{k,o,a}}go.onclick=()=>{try{let z=walk(JSON.parse(i.value));o.textContent=`Keys: ${z.k} · Objects: ${z.o} · Arrays: ${z.a}`}catch(e){o.textContent='Invalid JSON.'}}</script><?php smarttoolz_tool_page_end(); ?>